import sys
from itertools import combinations, permutations

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))
    k = int(next(iterator))

    grid = []
    for _ in range(n):
        row = []
        for _ in range(m):
            row.append(int(next(iterator)))
        grid.append(row)

    important_coords = []
    for _ in range(k):
        r = int(next(iterator)) - 1
        c = int(next(iterator)) - 1
        important_coords.append((r, c))

    important_set = set(important_coords)

    if k == 1:
        total_cost = grid[important_coords[0][0]][important_coords[0][1]]
        plan = [['.' for _ in range(m)] for _ in range(n)]
        plan[important_coords[0][0]][important_coords[0][1]] = 'X'
        print(total_cost)
        for row in plan:
            print(''.join(row))
        return

    def get_neighbors(r, c):
        neighs = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                neighs.append((nr, nc))
        return neighs

    from collections import deque

    def bfs_dist(start_r, start_c, target_set):
        dist = {}
        q = deque()
        q.append((start_r, start_c))
        dist[(start_r, start_c)] = 0

        while q:
            r, c = q.popleft()
            if (r, c) in target_set:
                continue
            d = dist[(r, c)]
            for nr, nc in get_neighbors(r, c):
                if (nr, nc) not in dist:
                    dist[(nr, nc)] = d + 1
                    q.append((nr, nc))
        return dist

    def get_path(start, end, dist_map):
        if end not in dist_map:
            return None
        path = [end]
        curr = end
        while curr != start:
            r, c = curr
            d = dist_map[curr]
            found = False
            for nr, nc in get_neighbors(r, c):
                nd = dist_map.get((nr, nc))
                if nd is not None and nd == d - 1:
                    curr = (nr, nc)
                    path.append(curr)
                    found = True
                    break
            if not found:
                return None
        return path[::-1]

    min_total_cost = float('inf')
    best_plan = None

    for perm in permutations(important_coords):
        current_plan = [['.' for _ in range(m)] for _ in range(n)] 
        current_cost = 0
        possible = True

        for idx in range(len(perm)):
            r1, c1 = perm[idx]
            if idx > 0:
                r0, c0 = perm[idx-1]
            else:
                r0, c0 = r1, c1

            if current_plan[r1][c1] == 'X':
                continue

            target_set = {(r1, c1)}
            dist = bfs_dist(r0, c0, target_set)

            if (r1, c1) not in dist:
                possible = False
                break

            path = get_path((r0, c0), (r1, c1), dist)
            if path is None:
                possible = False
                break

            for r, c in path:
                if current_plan[r][c] == '.':
                    current_plan[r][c] = 'X'
                    current_cost += grid[r][c]

        if possible:
            if current_cost < min_total_cost:
                min_total_cost = current_cost
                best_plan = [row[:] for row in current_plan]

    print(min_total_cost)
    for row in best_plan:
        print(''.join(row))

solve()
